test("3 桁の hex は、各桁を重ねた 6 桁の RGB になる", () => {
  expect(Rgb.create("#ABC")).toEqual(Option.some("#aabbcc"));
});

test.each([
  "#ffff",
  "#abcf",
  "#aabbccff",
  "#3b82f6ff",
  "3b82f6",
  "rgb(59, 130, 246)",
])("6 桁の hex にも 3 桁の短縮形にも当たらない値 %s は RGB にできない", (value) => {
  expect(Rgb.create(value)).toEqual(Option.none);
});

test("色の hex に `#` 無しで打った 6 桁で色が変わり、不透明度は残る", () => {
  const color = selectedHexControl("colors", "veil");

  expect(TokenControl.valueFromHex(color.target, "00ff00")).toEqual(
    Option.some({ kind: "colors", value: "#00ff0080" }),
  );
});

test("色の hex に `#` 付きで打った 6 桁でも色が変わる", () => {
  const color = selectedHexControl("colors", "primary");

  expect(TokenControl.valueFromHex(color.target, "#00ff00")).toEqual(
    Option.some({ kind: "colors", value: "#00ff00" }),
  );
});

test("色の hex に大文字で打った 6 桁は小文字で保存される", () => {
  const color = selectedHexControl("colors", "primary");

  expect(TokenControl.valueFromHex(color.target, "ABCDEF")).toEqual(
    Option.some({ kind: "colors", value: "#abcdef" }),
  );
});

test.each([
  "abc",
  "#ABC",
])("色の hex に打った 3 桁 %s は広げた 6 桁になり、不透明度は残る", (raw) => {
  const color = selectedHexControl("colors", "veil");

  expect(TokenControl.valueFromHex(color.target, raw)).toEqual(
    Option.some({ kind: "colors", value: "#aabbcc80" }),
  );
});

test.each([
  "abcf",
  "#abcf",
  "aabbccff",
  "#aabbccff",
  "abcd",
])("色の hex に打った 4 桁・8 桁 %s は alpha が不透明でも色を変えない", (raw) => {
  const color = selectedHexControl("colors", "primary");

  expect(TokenControl.valueFromHex(color.target, raw)).toEqual(Option.none);
});

test("読めない色のテキスト欄に `#` 無しの 3 桁を打っても色を変えない", () => {
  const color = selectedColorControl("colors", "broken");

  expect(TokenControl.valueFrom(color.target, "abc")).toEqual(Option.none);
});

test("影の色の hex に `#` 無しで打った 6 桁で影の色が変わり、不透明度は残る", () => {
  const color = selectedHexControl("shadows", "sm");

  expect(TokenControl.valueFromHex(color.target, "ff0000")).toEqual(
    Option.some({
      kind: "shadows",
      value: { x: 0, y: 1, blur: 3, color: "#ff00001a" },
    }),
  );
});

test("読めない色の stop のテキスト欄に `#` 無しの 6 桁を打っても色を変えない", () => {
  const [stop] = gradientOf(
    gradientSelectionOf({
      stops: [
        { color: "RED", ratio: 0 },
        { color: "#ffffff", ratio: 1 },
      ],
    }),
  ).stops;

  expect(TokenControl.valueFrom(stop.color.target, "ff0000")).toEqual(
    Option.none,
  );
});

test("影の色のピッカーから `#` 無しの 6 桁が届いても色を変えない", () => {
  const color = selectedHexControl("shadows", "sm");

  expect(TokenControl.valueFrom(color.target, "ff0000")).toEqual(Option.none);
});

test("色を選ぶと、見本・hex・不透明度が 1 行の色の欄にまとまる", () => {
  expect(rowsOf("colors", "primary")).toEqual([
    {
      kind: "color",
      color: {
        kind: "hex",
        target: { kind: "colors", color: "#3b82f6" },
        caption: { name: "hex", label: "hex" },
        rgb: "#3b82f6",
        alphaPercent: 100,
        picker: { name: "value", label: "値" },
        alpha: { name: "alpha", label: "不透明度" },
      },
    },
  ]);
});

test("stop の行は比率の欄と、見本・hex・不透明度の箱を持つ", () => {
  const [row] = gradientOf(gradientSelectionOf({ stops: TwoStops })).stops;
  const color = hexControlOf(row.color);

  expect(row.ratio.label).toBe("stop 1 の比率");
  expect([color.picker.label, color.caption.label, color.alpha.label]).toEqual([
    "stop 1 の色",
    "stop 1 の hex",
    "stop 1 の不透明度",
  ]);
});

test("箱の書き戻し先は色トークン・影の色・stop の色の 3 つで、影は色のフィールドだけを指す", () => {
  expectTypeOf<TokenColorTarget["kind"]>().toEqualTypeOf<
    "colors" | "shadows" | "gradientsStopColor"
  >();
  expectTypeOf<
    Extract<TokenColorTarget, { kind: "shadows" }>["field"]
  >().toEqualTypeOf<"color">();
});

test("field の行は色も階調も書き戻さず、影は数値のフィールドだけを指す。stop の比率の欄は比率、角度の欄は角度だけを書き戻す", () => {
  type FieldRowTarget = Extract<
    TokenControlRow,
    { kind: "field" }
  >["field"]["target"];
  expectTypeOf<FieldRowTarget["kind"]>().toEqualTypeOf<
    "spacing" | "radius" | "shadows" | "typography"
  >();
  expectTypeOf<
    Extract<FieldRowTarget, { kind: "shadows" }>["field"]
  >().toEqualTypeOf<ShadowNumberField>();
  expectTypeOf<
    GradientStopRow["ratio"]["target"]["kind"]
  >().toEqualTypeOf<"gradientsStopRatio">();
  expectTypeOf<
    GradientControl["angle"]["target"]["kind"]
  >().toEqualTypeOf<"gradientsAngle">();
});

test("値を変えない綴りで確定しても、欄は小文字の 6 桁へ取り直される", async () => {
  const user = userEvent.setup();
  renderColor("#3b82f6");

  await user.clear(hexField());
  await user.type(hexField(), "3B82F6{Enter}");

  expect(hexField().value).toBe("3b82f6");
});

test("弾かれた hex は打った文字列が欄に残り、値は届かない", async () => {
  const user = userEvent.setup();
  const onSetTokenValue = renderColor("#3b82f6");

  await user.clear(hexField());
  await user.type(hexField(), "abcd{Enter}");

  expect(hexField().value).toBe("abcd");
  expect(onSetTokenValue).not.toHaveBeenCalled();
});

test("読めない色が外から別の読めない綴りに変わると、`値` の欄もその綴りになる", () => {
  const { rerender } = render(colorBody("RED", () => {}));

  rerender(colorBody("BLUE", () => {}));

  expect(screen.getByLabelText<HTMLInputElement>("値").value).toBe("BLUE");
});

test("stop の hex を `#` 無しで確定すると、その stop だけが変わった値が届く", async () => {
  const user = userEvent.setup();
  const onSetTokenValue = renderGradient(TwoStops);

  await user.clear(screen.getByLabelText("stop 2 の hex"));
  await user.type(screen.getByLabelText("stop 2 の hex"), "ff0000{Enter}");

  expect(onSetTokenValue).toHaveBeenCalledWith(
    {
      kind: "gradients",
      value: {
        shape: "linear",
        angle: 90,
        stops: [TwoStops[0], { color: "#ff0000", ratio: 1 }],
      },
    },
    EditContinuities.Separate,
  );
});

test("色の hex を `#` 無しで打って確定すると一覧の値が変わる", async () => {
  await renderTokensView();
  await selectRow("primary");

  await userEvent.clear(field("hex"));
  await userEvent.type(field("hex"), "ff0000{Enter}");

  expect(row("primary #ff0000")).toBeDefined();
});

test("ピッカーで色を変えると、hex の欄が `#` 無しで追随する", async () => {
  await renderTokensView();
  await selectRow("primary");

  fireEvent.change(field("値"), { target: { value: "#00ff00" } });

  expect(field("hex")).toHaveProperty("value", "00ff00");
});

/*
 * 確定の回数を key に混ぜるのは、`ABC` のように通っても値が変わらない確定では key が動かず下書きが残るため。
 * 回数はこの欄の表示だけが使い、文書（undo の履歴ごと親が持つ）と連動しないので reducer にまとめない。
 * `changeRawOf` に成否を返させないのは、成否を使わない他の呼び出し側まで戻り値を受けることになるため。
 */
const [hexCommits, setHexCommits] = useState(0);
const commitHex = (raw: string) => {
  const value = TokenControl.valueFromHex(color.target, raw);
  if (!Option.isSome(value)) {
    return;
  }

  onSetTokenValue(value.value, EditContinuities.Separate);
  setHexCommits((count) => count + 1);
};
